function buildClothing(){if(!g.DNDCharacterClothing)return;var box=el('ceGroup_clothing');g.DNDCharacterClothing.slots.forEach(function(slot){var label=document.createElement('label');label.id='ceClothingRow_'+slot.id;label.style.cssText='display:block;margin:12px 0';label.textContent=slot.name;var select=document.createElement('select');select.id='ceClothing_'+slot.id;select.style.cssText='display:block;width:100%;margin-top:6px';select.onchange=function(){setClothing(slot.id,this.value);};label.appendChild(select);box.appendChild(label);});var denLabel=document.createElement('label');denLabel.id='ceHosieryDenRow';denLabel.style.cssText='display:block;margin:12px 0';denLabel.textContent='Плотность капрона (DEN)';var den=document.createElement('select');den.id='ceHosieryDen';den.style.cssText='display:block;width:100%;margin-top:6px';g.DNDCharacterClothing.denValues.forEach(function(value){var o=document.createElement('option');o.value=value;o.textContent=value+' DEN';den.appendChild(o);});den.onchange=function(){setHosieryDen(this.value);};denLabel.appendChild(den);box.insertBefore(denLabel,el('ceClothingRow_feet'));var hint=document.createElement('p');hint.className='ceHint';hint.textContent='Бельё включено по умолчанию, его можно снять. Одежда подстраивается под пропорции тела. Юбка и штаны занимают один слот. Платье заменяет верх и низ; их выбор сохраняется. Корсет можно носить поверх рубашки или платья.';box.appendChild(hint);buildCustomizer(box);}
